const item = $input.first();
const keys = Object.keys(item.binary || {});
let name = '';
const reject = message => [{json:{summary:{file_name:name,processed_rows:0,imported_transactions:0,skipped_duplicates:0,invalid_rows:0,status:'rejected',errors:[{message}]}}}];
if (keys.length !== 1) return reject('Upload exactly one CSV, XLSX or PDF file.');
const file = item.binary[keys[0]];
name = (file.fileName || '').replace(/[\\/]/g,'_').slice(0,255);
const extension = name.split('.').pop().toLowerCase();
if (!['csv','xlsx','pdf'].includes(extension)) return reject('Only CSV, XLSX and text PDF files are supported.');
const buffer = await this.helpers.getBinaryDataBuffer(0, keys[0]);
if (!buffer.length || buffer.length > 2*1024*1024) return reject('File must be nonempty and at most 2 MiB.');
if (extension === 'pdf' && !buffer.subarray(0,1024).toString().includes('%PDF-')) return reject('Invalid PDF file.');
if (extension === 'xlsx') {
  if (buffer.length < 4 || buffer.readUInt32LE(0) !== 0x04034b50) return reject('Invalid XLSX container.');
  let expanded = 0;
  for (let i=0; i+46<buffer.length; i++) {
    if (buffer.readUInt32LE(i) === 0x02014b50) {
      expanded += buffer.readUInt32LE(i+24);
      if (expanded > 10*1024*1024) return reject('Expanded workbook exceeds 10 MiB.');
    }
  }
}
return [{json:{file_name:name,extension},binary:{statement:file}}];

const metadata = $('Hash Statement').first().json;
const items = $input.all();
const reject = message => [{json:{summary:{file_name:metadata.file_name,processed_rows:0,imported_transactions:0,skipped_duplicates:0,invalid_rows:0,status:'rejected',errors:[{message}]}}}];
if (items[0]?.json.summary) return items;
if (items.some(i=>i.json.error)) return reject('File extraction failed. Check the file format and header.');
const rows = items[0]?.json.pdf_rows ?? items.filter(i=>Object.keys(i.json).length).map(i=>i.json);
if (!rows.length) return reject('No transaction rows found in the file.');
if (rows.length > 5000) return reject('Statement exceeds the 5000-row limit.');
return [{json:{...metadata,rows,pdf_complete:items[0]?.json.pdf_complete}}];

const s = {...($json.summary || $json.previous_summary || {})};
const pdf = $('Hash Statement').isExecuted && $('Hash Statement').first().json.extension==='pdf';
if (pdf) s.warning = 'PDF import rozpoznává transakce automaticky. Zkontrolujte počty a částky oproti výpisu; některé položky mohou chybět.';
if (pdf && $('Prepare Import Batch').isExecuted && $('Prepare Import Batch').first().json.pdf_complete===false && s.status==='completed') s.status='partial';
const escape = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const title = ({completed:'Import dokončen',partial:'Částečný import',duplicate_file:'Výpis už byl nahrán',rejected:'Import se nepodařil'})[s.status] || 'Výsledek importu';
const labels = {file_name:'Soubor',processed_rows:'Zpracované řádky',imported_transactions:'Nové transakce',skipped_duplicates:'Přeskočené duplicity',invalid_rows:'Chybné řádky'};
const fields = Object.entries(labels).map(([key,label])=>'<dt>'+label+'</dt><dd>'+escape(s[key])+'</dd>').join('');
const errors = (s.errors || []).map(e=>'<li>'+escape((e.row ? 'Řádek '+e.row+': ' : '')+e.message)+'</li>').join('');
const html = '<!doctype html><html lang="cs"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>'+title+'</title><body style="font:16px system-ui;max-width:760px;margin:40px auto;padding:20px"><h1>'+title+'</h1><dl>'+fields+'</dl>'+(s.warning?'<p>'+escape(s.warning)+'</p>':'')+(errors?'<ul>'+errors+'</ul>':'')+'<p><a id="upload-another" href="/form/finance-import" target="_top" style="display:inline-block;padding:12px 20px;background:#2264db;color:white;border-radius:6px;text-decoration:none">Nahrát další výpis</a></p><details><summary>Podrobnosti importu</summary><pre id="import-summary">'+escape(JSON.stringify(s,null,2))+'</pre></details></body></html>';
return [{json:{summary:s,report:html}}];

const metadata = $('Hash Statement').first().json;
const reject = message => [{json:{summary:{file_name:metadata.file_name,processed_rows:0,imported_transactions:0,skipped_duplicates:0,invalid_rows:0,status:'rejected',errors:[{message}]}}}];
if ($json.error) return reject('PDF could not be opened. Use an unencrypted text PDF.');
if ($json.numpages > 20) return reject('PDF exceeds the 20-page limit.');
const text = String($json.text || '').normalize('NFC').trim();
if (!text) return reject('PDF contains no readable text. Scanned PDFs require OCR; use CSV/XLSX instead.');
if (text.length > 30000) return reject('PDF text exceeds 30000 characters. Upload a shorter statement or CSV/XLSX.');
return [{json:{text}}];

const data = $json.output;
const source = $('Check PDF Text').first().json.text.replace(/\s+/g,' ');
const metadata = $('Hash Statement').first().json;
const reject = message => [{json:{summary:{file_name:metadata.file_name,processed_rows:0,imported_transactions:0,skipped_duplicates:0,invalid_rows:0,status:'rejected',errors:[{message}]}}}];
if (!data || !Array.isArray(data.transactions)) return reject('Local PDF extraction failed. Try a smaller text PDF or CSV/XLSX.');
if (!data.transactions.length) return reject('No bank transactions were recognized in the PDF.');
if (data.transactions.length > 100) return reject('PDF extraction exceeds 100 transactions. Use CSV/XLSX for larger statements.');
const clean = v => String(v ?? '').normalize('NFC').replace(/\s+/g,' ').trim();
const dateKey = v => {
  let m = String(v).match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (m) return m[1]+'-'+m[2]+'-'+m[3];
  m = String(v).match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})$/);
  return m ? m[3]+'-'+m[2].padStart(2,'0')+'-'+m[1].padStart(2,'0') : '';
};
const moneyKey = v => {
  const s = clean(v).replace(/\s/g,'').replace(/\u2212/g,'-').replace(',','.');
  if (!/^[+-]?\d+(\.\d{1,2})?$/.test(s)) return '';
  const p = s.replace(/^\+/,'').split('.');
  return p[0].replace(/^(-?)0+(?=\d)/,'$1')+'.'+(p[1]||'').padEnd(2,'0');
};
const rows = data.transactions.map(t => {
  const quote = clean(t.source_excerpt);
  const date = dateKey(t.date);
  const amount = moneyKey(t.amount);
  const dates = [...quote.matchAll(/\b\d{4}-\d{2}-\d{2}\b|\b\d{1,2}\.\d{1,2}\.\d{4}\b/g)].map(m=>dateKey(m[0]));
  const withoutDates = quote.replace(/\b\d{4}-\d{2}-\d{2}\b|\b\d{1,2}\.\d{1,2}\.\d{4}\b/g,'');
  const amounts = [...withoutDates.matchAll(/(?<![\d.,])[-+\u2212]?\s*(?:\d{1,3}(?: \d{3})+|\d+)(?:[.,]\d{1,2})?(?![\d.,])/g)].map(m=>moneyKey(m[0]));
  const currency = clean(t.currency).toUpperCase();
  const description = clean(t.description);
  const merchant = clean(t.merchant);
  const id = clean(t.transaction_id);
  const type = clean(t.transaction_type).toLowerCase();
  const amountSupported = amounts.includes(amount) || (amount.startsWith('-') && amounts.includes(amount.slice(1)) && /debit|výdaj|odchoz|payment|purchase|platba/i.test(quote));
  const currencySupported = source.includes(currency) || (currency==='CZK' && /Kč/i.test(source)) || (currency==='EUR' && source.includes('€'));
  const valid = quote.length>=10 && quote.length<=1500 && source.includes(quote) && dates.includes(date) &&
    amount && amountSupported && ['CZK','EUR','USD','GBP','PLN','CHF'].includes(currency) && currencySupported &&
    description && quote.toLowerCase().includes(description.toLowerCase()) &&
    (!merchant || quote.toLowerCase().includes(merchant.toLowerCase())) && (!id || quote.includes(id)) &&
    (!['refund','transfer'].includes(type) || (type==='refund' ? /refund|vrat|vrác|return/i.test(quote) : /internal transfer|own accounts?|mezi.*vlastn.*účt|převod.*vlastn|vlastní.*účet/i.test(quote)));
  return valid ? {date,amount,currency,description,merchant,transaction_id:id,transaction_type:type}
    : {date:'',amount:'',currency:'',description:'',merchant:'',transaction_id:'',_pdf_validation_error:true};
});
return [{json:{pdf_rows:rows,pdf_complete:data.complete===true}}];
